pub fn contains(list: &Vec<i32>, element: i32) -> bool {
    // Linear scan; does not modify the input.
    for &x in list.iter() {
        if x == element {
            return true;
        }
    }
    false
}

pub fn has_common_element(list1: &Vec<i32>, list2: &Vec<i32>) -> bool {
    // If either list is empty, there cannot be a common element.
    if list1.is_empty() || list2.is_empty() {
        return false;
    }

    // Scan list1 and test membership in list2.
    for &x in list1.iter() {
        if contains(list2, x) {
            return true;
        }
    }
    false
}

